<?php
// Giao diện quản lý danh mục sản phẩm.
 $escape = static fn (mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); ?>
<section class="admin-page">
    <p class="admin-eyebrow"><a href="<?php echo $escape($baseUrl.'/admin'); ?>">Quản trị</a> / UC12</p><h1>Quản lý danh mục</h1>
    <?php if ($error !== '') { ?><p class="admin-message error" role="alert"><?php echo $escape($error); ?></p><?php } ?>
    <?php if ($success !== '') { ?><p class="admin-message success" role="status"><?php echo $escape($success); ?></p><?php } ?>
    <section class="admin-form"><h2>Thêm danh mục</h2><form method="post" action="<?php echo $escape($baseUrl.'/admin/categories/save'); ?>"><input type="hidden" name="_csrf" value="<?php echo $escape($csrfToken); ?>"><label>Tên danh mục <input name="name" maxlength="100" required></label><button type="submit">Thêm danh mục</button></form></section>
    <div class="admin-table-wrap"><table><thead><tr><th>Mã</th><th>Tên danh mục</th><th>Số sản phẩm</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>
    <?php foreach ($categories as $category) { ?><tr><td><?php echo $escape($category['MaDM']); ?></td><td><form class="inline-form" method="post" action="<?php echo $escape($baseUrl.'/admin/categories/save'); ?>"><input type="hidden" name="_csrf" value="<?php echo $escape($csrfToken); ?>"><input type="hidden" name="category_id" value="<?php echo $escape($category['MaDM']); ?>"><input name="name" maxlength="100" required value="<?php echo $escape($category['TenDM']); ?>"><button type="submit">Lưu tên</button></form></td><td><?php echo $escape($category['SoSanPham']); ?></td><td><?php echo $escape($category['TrangThai'] === 'NgungKinhDoanh' ? 'Ngừng kinh doanh' : 'Đang kinh doanh'); ?></td><td><form class="inline-form" method="post" action="<?php echo $escape($baseUrl.'/admin/categories/status'); ?>"><input type="hidden" name="_csrf" value="<?php echo $escape($csrfToken); ?>"><input type="hidden" name="category_id" value="<?php echo $escape($category['MaDM']); ?>"><input type="hidden" name="status" value="<?php echo $category['TrangThai'] === 'NgungKinhDoanh' ? 'DangKinhDoanh' : 'NgungKinhDoanh'; ?>"><button type="submit"><?php echo $category['TrangThai'] === 'NgungKinhDoanh' ? 'Kinh doanh lại' : 'Ngừng kinh doanh'; ?></button></form><?php if ((int) $category['SoSanPham'] === 0) { ?><form class="inline-form" method="post" action="<?php echo $escape($baseUrl.'/admin/categories/delete'); ?>" onsubmit="return confirm('Xóa danh mục này?')"><input type="hidden" name="_csrf" value="<?php echo $escape($csrfToken); ?>"><input type="hidden" name="category_id" value="<?php echo $escape($category['MaDM']); ?>"><button class="danger-button" type="submit">Xóa</button></form><?php } ?></td></tr><?php } ?>
    <?php if ($categories === []) { ?><tr><td colspan="5">Chưa có danh mục.</td></tr><?php } ?>
    </tbody></table></div>
</section>
